import { type Page } from '@playwright/test';

import { invoiceRun, type InvoiceRun } from './invoice-fixtures';

// TASK-060's browser fixtures (routes/fixtures.php; ExportFixture): the Owner signed in with a company of the run and
// one issued invoice of Rp1,000,000 — TASK-049's InvoiceFixture —; and the run's PENDING exports generated by the job
// itself, as a queue worker would, since the local stack runs none for the browser suite.

export async function reportRun(page: Page, run: string, locale: 'id' | 'en' = 'id'): Promise<InvoiceRun> {
    return invoiceRun(page, run, { stage: 'issued', locale });
}

export async function runExports(page: Page): Promise<number> {
    const response = await page.request.post('/__fixtures/ekspor/jalankan');

    if (!response.ok()) {
        throw new Error(`The export fixture failed: ${String(response.status())} ${await response.text()}`);
    }

    return ((await response.json()) as { ran: number }).ran;
}
